code:
АдресAPI = ЭтотОбъект.Объект.АдресGitAPI;
Репозиторий = ЭтотОбъект.Объект.РепозиторийGit;
Ветка = ЭтотОбъект.Объект.ВеткаGit;
Токен = ЭтотОбъект.Объект.ТокенGit;
КаталогЗнаний = ЭтотОбъект.Объект.КаталогБазыЗнанийGit;

АдресБезПротокола = АдресAPI;
Протокол = "https";
Если Лев(АдресБезПротокола, 8) = "https://" Тогда
	АдресБезПротокола = Сред(АдресБезПротокола, 9);
ИначеЕсли Лев(АдресБезПротокола, 7) = "http://" Тогда
	Протокол = "http";
	АдресБезПротокола = Сред(АдресБезПротокола, 8);
КонецЕсли;

ПозицияСлэша = Найти(АдресБезПротокола, "/");
Если ПозицияСлэша > 0 Тогда
	Хост = Лев(АдресБезПротокола, ПозицияСлэша - 1);
Иначе
	Хост = АдресБезПротокола;
КонецЕсли;

Если Протокол = "https" Тогда
	ЗащСоединение = Новый ЗащищенноеСоединениеOpenSSL();
Иначе
	ЗащСоединение = Неопределено;
КонецЕсли;

Соединение = Новый HTTPСоединение(Хост, 443, , , , 30, ЗащСоединение);

URL = "/repos/" + Репозиторий + "/contents/" + КаталогЗнаний + "?ref=" + Ветка;

Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "Bearer " + Токен);
Запрос = Новый HTTPЗапрос(URL, Заголовки);

Попытка
	Ответ = Соединение.Получить(Запрос);
	Если Ответ.КодСостояния = 200 Тогда
		ТелоОтвета = Ответ.ПолучитьТелоКакСтроку();
		Чтение = Новый ЧтениеJSON;
		Чтение.ОткрытьСтроку(ТелоОтвета);
		МассивФайлов = ПрочитатьJSON(Чтение);
		Чтение.Закрыть();
		КоличествоФайлов = 0;
		Если ТипЗнч(МассивФайлов) = Тип("Массив") Тогда
			КоличествоФайлов = МассивФайлов.Количество();
		КонецЕсли;
		Результат = "В базе знаний найдено файлов: " + КоличествоФайлов;
	Иначе
		Результат = "Ошибка запроса. Код: " + Ответ.КодСостояния;
	КонецЕсли;
Исключение
	Результат = "Ошибка: " + ОписаниеОшибки();
КонецПопытки;

Сообщить(Результат);
